        // one likely is too; a tip would not stay up long enough to be read.
        var lastBootMs = parseInt(get('SUP_LAST_BOOT_MS'), 10);
        if (!isNaN(lastBootMs) && lastBootMs < 2000) {
          root.setAttribute('data-sp-quick-boot', '');
        }

