      }

      .app-loading .productivity-tip h2#heading {
        font:
          500 14px/20px 'Open Sans',
          'Helvetica Neue',
          sans-serif;
        margin: 0 0 4px !important;
        color: inherit;
      }

      .app-loading .productivity-tip p {
        font:
          400 13px/19px 'Open Sans',
          'Helvetica Neue',
          sans-serif;
        margin: 0 !important;
      }

      [data-sp-quick-boot] .productivity-tip {
        display: none;
      }

      @keyframes sp-fade-in {
        from {
          opacity: 0;
        }
      }

      @keyframes sp-pulse {
        0%,
        100% {
          opacity: 0;
          transform: scale(0.8);
        }
        50% {
          opacity: 0.12;
          transform: scale(1);
        }
      }

      @media (prefers-reduced-motion: reduce) {
        .productivity-tip,
        .app-loading .spinner-pulse {
          animation: none;
        }
      }
